/**
 * API Schema Query Functions
 *
 * Loads the generated API schema index and provides query functions
 * for the `sentry schema` command. The schema is generated by
 * `script/generate-api-schema.ts` from Sentry's OpenAPI specification.
 */

import endpoints from "../generated/api-schema.json";

/** Searchable query parameter metadata from the pinned OpenAPI specification. */
export type ApiQueryParameter = {
  name: string;
  description?: string;
  type?: string;
  required: boolean;
  enum?: (string | number | boolean | null)[];
};

/** An API used by a command, with context rather than a claim of equivalence. */
export type ApiReference = {
  fn: string;
  note?: string;
};

export type CommandApiReference = ApiReference & { command: string };

/** Discovery evidence is additive; exact lookups return plain ApiEndpoints. */
export type SchemaEndpoint = ApiEndpoint & {
  match?: {
    reasons: string[];
    relatedCommands: { command: string; note?: string }[];
  };
};

/** A single API endpoint entry from the generated schema */
export type ApiEndpoint = {
  /** SDK function name from @sentry/api (empty string if unmapped) */
  fn: string;
  /** HTTP method (GET, POST, PUT, DELETE, PATCH) */
  method: string;
  /** URL path template with {param} placeholders */
  path: string;
  /** Human-readable description of the endpoint */
  description: string;
  summary?: string;
  tags?: string[];
  /** Path parameter names extracted from the URL template */
  pathParams: string[];
  /** Query parameter names from the OpenAPI spec */
  queryParams: string[];
  queryParameters?: ApiQueryParameter[];
  /** Whether the endpoint is deprecated */
  deprecated: boolean;
  /** Resource group name derived from URL (e.g., "projects", "issues") */
  resource: string;
  /** Human-readable operation ID from OpenAPI (e.g., "List an Organization's Issues") */
  operationId: string;
};

/** Summary of a resource group with its operations */
export type ResourceSummary = {
  /** Resource group name */
  name: string;
  /** Number of endpoints in this resource */
  endpointCount: number;
  /** List of distinct HTTP methods available */
  methods: string[];
};

/** Type the imported JSON array */
const schema = endpoints as ApiEndpoint[];

const HTTP_METHOD_PREFIX = /^(GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\s+/i;
const HTTP_URL_PREFIX = /^https?:\/\//i;
const WHITESPACE = /\s/;

/** Parsed `METHOD /path` or `/api/...` query used by `sentry schema`. */
export type ParsedEndpointQuery = {
  /** Uppercase HTTP method when the query starts with one */
  method?: string;
  /** Normalized API path when the query looks like one */
  path?: string;
  /** Remainder after stripping a leading HTTP method */
  text: string;
};

/**
 * Parse `GET /api/0/...`, `/api/0/...`, or a keyword.
 * Path-shaped input includes `/api/...`, `api/0/...`, and full Sentry URLs.
 */
export function parseEndpointQuery(query: string): ParsedEndpointQuery {
  const trimmed = query.trim();
  if (!trimmed) {
    return { text: "" };
  }

  const methodMatch = trimmed.match(HTTP_METHOD_PREFIX);
  const method = methodMatch?.[1]?.toUpperCase();
  const afterMethod = methodMatch
    ? trimmed.slice(methodMatch[0].length).trim()
    : trimmed;

  const path = extractApiPath(afterMethod);
  if (path) {
    return { method, path, text: afterMethod };
  }
  return { method, text: afterMethod };
}

/**
 * Find endpoints whose path matches `path`, optionally filtered by HTTP method.
 * `{param}` in the schema matches a concrete slug; an OpenAPI-style query
 * (`{param}` in the input) only matches schema params at that segment.
 */
export function findEndpointsByPath(
  path: string,
  method?: string,
  catalog: readonly ApiEndpoint[] = schema,
): ApiEndpoint[] {
  const methodUpper = method?.toUpperCase();
  const normalized = normalizeApiPath(path);
  const candidates = catalog.filter((endpoint) => {
    if (methodUpper && endpoint.method !== methodUpper) {
      return false;
    }
    return pathsEquivalent(endpoint.path, normalized);
  });
  if (candidates.length <= 1) {
    return candidates;
  }

  const exact = candidates.filter(
    (endpoint) => normalizeApiPath(endpoint.path) === normalized,
  );
  if (exact.length > 0) {
    return exact;
  }

  let bestScore = -1;
  const ranked: ApiEndpoint[] = [];
  for (const endpoint of candidates) {
    const score = literalSegmentScore(endpoint.path, normalized);
    if (score > bestScore) {
      bestScore = score;
      ranked.length = 0;
      ranked.push(endpoint);
    } else if (score === bestScore) {
      ranked.push(endpoint);
    }
  }
  return ranked;
}

/**
 * Find endpoints by an exact SDK function name or OpenAPI operation ID.
 *
 * Matching is case-insensitive but deliberately not fuzzy: partial operation
 * names can match many unrelated endpoints and should use `--search` instead.
 */
export function findEndpointsByIdentifier(
  identifier: string,
  catalog: readonly ApiEndpoint[] = schema,
): ApiEndpoint[] {
  const normalized = identifier.trim().toLowerCase();
  if (!normalized) {
    return [];
  }
  return catalog.filter(
    (endpoint) =>
      endpoint.fn.toLowerCase() === normalized ||
      endpoint.operationId.toLowerCase() === normalized,
  );
}

/** Get all unique resource names, sorted alphabetically */
export function getAllResources(): string[] {
  const resources = new Set(schema.map((e) => e.resource));
  return [...resources].sort();
}

/** Get all endpoints for a given resource name (case-insensitive) */
export function getEndpointsByResource(resource: string): ApiEndpoint[] {
  const lower = resource.toLowerCase();
  return schema.filter((e) => e.resource.toLowerCase() === lower);
}

const CAMEL_CASE_BOUNDARY = /([a-z0-9])([A-Z])/g;
const WORD_SEPARATOR = /[^a-z0-9]+/;
const PARAM_PLACEHOLDER = /\{[^}]+\}/g;

/** Conservative English plurals for discovery only, never endpoint identity. */
function normalizeWord(word: string): string {
  if (word.length > 4 && word.endsWith("ies")) {
    return `${word.slice(0, -3)}y`;
  }
  if (
    word.length > 3 &&
    word.endsWith("s") &&
    !word.endsWith("ss") &&
    !word.endsWith("us") &&
    !word.endsWith("is")
  ) {
    return word.slice(0, -1);
  }
  return word;
}

function words(text: string): Set<string> {
  return new Set(
    text
      .replace(CAMEL_CASE_BOUNDARY, "$1 $2")
      .toLowerCase()
      .split(WORD_SEPARATOR)
      .filter(Boolean)
      .map(normalizeWord),
  );
}

type SearchField = { text: string; reason: string; weight: number };

function searchFields(endpoint: ApiEndpoint): SearchField[] {
  const fields: SearchField[] = [
    {
      text: endpoint.resource,
      reason: `API resource: ${endpoint.resource}`,
      weight: 80,
    },
    { text: endpoint.summary ?? "", reason: "Operation summary", weight: 60 },
    {
      text: `${endpoint.fn} ${endpoint.operationId}`,
      reason: "Operation name",
      weight: 40,
    },
    {
      text: endpoint.path.replace(PARAM_PLACEHOLDER, ""),
      reason: "API path",
      weight: 30,
    },
    { text: endpoint.tags?.join(" ") ?? "", reason: "API tags", weight: 20 },
    { text: endpoint.description, reason: "Operation description", weight: 10 },
  ];
  for (const parameter of endpoint.queryParameters ?? []) {
    fields.push({
      text: parameter.name,
      reason: `Query parameter: ${parameter.name}`,
      weight: 20,
    });
    for (const value of parameter.enum ?? []) {
      fields.push({
        text: String(value),
        reason: `Query parameter: ${parameter.name}=${String(value)}`,
        weight: 100,
      });
    }
    if (parameter.description) {
      fields.push({
        text: parameter.description,
        reason: `Query parameter description: ${parameter.name}`,
        weight: 10,
      });
    }
  }
  return fields.sort((a, b) => b.weight - a.weight);
}

function matchEndpoint(
  endpoint: ApiEndpoint,
  tokens: Set<string>,
  references: readonly CommandApiReference[],
): { endpoint: SchemaEndpoint; score: number } | undefined {
  const relatedCommands = references
    .filter((ref) => ref.fn === endpoint.fn)
    .map(({ command, note }) => ({ command, ...(note ? { note } : {}) }));
  const scores = new Map<string, number>();
  const reasons: string[] = [];
  for (const field of searchFields(endpoint)) {
    const fieldWords = words(field.text);
    const matches = [...tokens].filter((token) => fieldWords.has(token));
    if (matches.length === 0) {
      continue;
    }
    for (const token of matches) {
      scores.set(token, Math.max(scores.get(token) ?? 0, field.weight));
    }
    reasons.push(field.reason);
  }
  if (relatedCommands.length === 0 && scores.size !== tokens.size) {
    return;
  }
  return {
    endpoint: { ...endpoint, match: { reasons, relatedCommands } },
    score: [...scores.values()].reduce(
      (sum, value) => sum + value,
      relatedCommands.length > 0 ? 1000 : 0,
    ),
  };
}

/**
 * Discover API capabilities, retaining why each candidate matched. All query
 * words must match, unless the CLI explicitly declares a related operation.
 * References must be scoped to this query by getCommandApiReferences; they
 * establish a semantic match even when the API uses different vocabulary.
 * Exact identifiers and paths keep their existing, unannotated JSON shape.
 */
export function searchEndpoints(
  query: string,
  catalog: readonly ApiEndpoint[] = schema,
  references: readonly CommandApiReference[] = [],
): SchemaEndpoint[] {
  const parsed = parseEndpointQuery(query);
  if (parsed.path) {
    return findEndpointsByPath(parsed.path, parsed.method, catalog);
  }
  const exact = findEndpointsByIdentifier(parsed.text, catalog).filter(
    (endpoint) => !parsed.method || endpoint.method === parsed.method,
  );
  if (exact.length > 0) {
    return exact;
  }
  const tokens = words(parsed.text);
  if (tokens.size === 0) {
    return [];
  }
  const matches: { endpoint: SchemaEndpoint; score: number }[] = [];
  for (const endpoint of catalog) {
    if (parsed.method && endpoint.method !== parsed.method) {
      continue;
    }
    const match = matchEndpoint(endpoint, tokens, references);
    if (match) {
      matches.push(match);
    }
  }
  // A stable tie-breaker prevents catalog insertion order from choosing an API.
  matches.sort(
    (a, b) =>
      Number(a.endpoint.deprecated) - Number(b.endpoint.deprecated) ||
      b.score - a.score ||
      a.endpoint.path.localeCompare(b.endpoint.path) ||
      a.endpoint.method.localeCompare(b.endpoint.method) ||
      a.endpoint.fn.localeCompare(b.endpoint.fn),
  );
  return matches.map((match) => match.endpoint);
}

function extractApiPath(input: string): string | undefined {
  const trimmed = input.trim();
  if (!trimmed) {
    return;
  }

  if (HTTP_URL_PREFIX.test(trimmed)) {
    const token = trimmed.split(WHITESPACE)[0] ?? trimmed;
    if (!URL.canParse(token)) {
      return;
    }
    const pathname = new URL(token).pathname;
    if (pathname.startsWith("/api/")) {
      return normalizeApiPath(pathname);
    }
    return;
  }

  const token = trimmed.split(WHITESPACE)[0] ?? trimmed;
  if (token.startsWith("/api/")) {
    return normalizeApiPath(token);
  }
  if (token.startsWith("api/0/") || token.startsWith("api/1/")) {
    return normalizeApiPath(`/${token}`);
  }
  return;
}

function normalizeApiPath(path: string): string {
  const noQuery = path.split("?")[0] ?? path;
  const withLeading = noQuery.startsWith("/") ? noQuery : `/${noQuery}`;
  return withLeading.endsWith("/") ? withLeading : `${withLeading}/`;
}

function isTemplateSegment(segment: string): boolean {
  return segment.startsWith("{") && segment.endsWith("}") && segment.length > 2;
}

function splitPath(path: string): string[] {
  return path.split("/").filter((segment) => segment.length > 0);
}

/**
 * Schema `{param}` matches a concrete slug. Query `{param}` only matches a
 * schema param — so an OpenAPI path does not collapse onto a static sibling
 * like `latest-base` or a shorter resource like `getProject`.
 */
function pathsEquivalent(schemaPath: string, queryPath: string): boolean {
  const left = normalizeApiPath(schemaPath);
  const right = normalizeApiPath(queryPath);
  if (left === right) {
    return true;
  }

  const leftSegs = splitPath(left);
  const rightSegs = splitPath(right);
  if (leftSegs.length !== rightSegs.length) {
    return false;
  }

  const queryIsTemplate = right.includes("{");
  return leftSegs.every((schemaSeg, i) => {
    const querySeg = rightSegs[i];
    if (querySeg === undefined) {
      return false;
    }
    if (schemaSeg === querySeg) {
      return true;
    }
    if (queryIsTemplate) {
      return isTemplateSegment(schemaSeg) && isTemplateSegment(querySeg);
    }
    return isTemplateSegment(schemaSeg);
  });
}

function literalSegmentScore(schemaPath: string, queryPath: string): number {
  const schemaSegs = splitPath(normalizeApiPath(schemaPath));
  const querySegs = splitPath(normalizeApiPath(queryPath));
  let score = 0;
  for (let i = 0; i < schemaSegs.length; i++) {
    if (schemaSegs[i] === querySegs[i]) {
      score += 1;
    }
  }
  return score;
}

/** Get all endpoints (returns a readonly reference to the internal array) */
export function getAllEndpoints(): readonly ApiEndpoint[] {
  return schema;
}

/** Get resource summary: name, endpoint count, and methods for each resource */
export function getResourceSummaries(): ResourceSummary[] {
  const map = new Map<
    string,
    { endpointCount: number; methods: Set<string> }
  >();

  for (const endpoint of schema) {
    const existing = map.get(endpoint.resource);
    if (existing) {
      existing.endpointCount += 1;
      existing.methods.add(endpoint.method);
    } else {
      map.set(endpoint.resource, {
        endpointCount: 1,
        methods: new Set([endpoint.method]),
      });
    }
  }

  return [...map.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, info]) => ({
      name,
      endpointCount: info.endpointCount,
      methods: [...info.methods].sort(),
    }));
}
